mkdir -p 'tests/framework/pbunit.pbl'
cat > 'tests/framework/pbunit.pbl/asynctestcase.sru' <<'PBUNIT_EOF'
//objectcomments Extends the test case to support rerunning in an async environment
forward
global type asynctestcase from testcase
end type
end forward

global type asynctestcase from testcase
end type
global asynctestcase asynctestcase

type variables
Private Boolean ib_rerun
end variables

forward prototypes
public subroutine runbare ()
public subroutine rerun ()
public function boolean shouldrerun ()
public function test suite ()
end prototypes

public subroutine runbare ();
if not shouldRerun() then
	this.event setUp()
end if

ib_rerun = false

this.event runTest()

if not shouldRerun() then
	this.event tearDown()
end if
end subroutine

public subroutine rerun ();ib_rerun = true
end subroutine

public function boolean shouldrerun ();return ib_rerun
end function

public function test suite ();AsyncTestSuite	lnv_suite

lnv_suite = create AsyncTestSuite
lnv_suite.initialize(className())
return lnv_suite
end function

on asynctestcase.create
TriggerEvent( this, "constructor" )
end on

on asynctestcase.destroy
TriggerEvent( this, "destructor" )
end on
PBUNIT_EOF

mkdir -p 'tests/framework/pbunit.pbl'
cat > 'tests/framework/pbunit.pbl/asynctestsuite.sru' <<'PBUNIT_EOF'
//objectcomments Extends test suite to run test cases in an async environment
forward
global type asynctestsuite from testsuite
end type
end forward

global type asynctestsuite from testsuite
event processtest ( )
end type
global asynctestsuite asynctestsuite

type variables
Private TestTimer inv_timer
Private pbunit_Iterator inv_iterator
Private Boolean ib_running
Private Test inv_currentTest
Private TestResult inv_currentResult

end variables

forward prototypes
public subroutine run (testresult anv_result)
end prototypes

event processtest;Test					lnv_emptyTest
pbunit_Iterator	lnv_emptyIterator
Boolean				lb_testFound

inv_timer.stop()

if isValid(inv_currentTest) then
	if inv_currentTest.shouldRerun() then
		lb_testFound = true
	end if
end if

if not lb_testFound then
	lb_testFound = inv_testCollection.iterate_into(inv_iterator, inv_currentTest) 
end if

if lb_testFound then
	inv_currentTest.run(inv_currentResult)
end if

if not lb_testFound or inv_currentResult.shouldStop() then
	inv_currentTest = lnv_emptyTest
	inv_iterator = lnv_emptyIterator
	ib_running = false
else
	inv_timer.start()
end if



end event

public subroutine run (testresult anv_result);
inv_currentResult = anv_result

